style.css:
@-moz-document domain("youtube.com") {
/* --- Variables Góticas --- */
  :root {
    --gothic-bg-darkest: #0a0a0a;     /* Fondo muy oscuro */
    --gothic-bg-dark: #121212;        /* Fondo de contenedores */
    --gothic-bg-medium: #1c1c1c;      /* Fondo de inputs/tarjetas */
    --gothic-text-light: #e0e0e0;     /* Texto principal claro */
    --gothic-text-medium: #a0a0a0;    /* Texto secundario gris */
    --gothic-red-accent: #8b0000;     /* Rojo sangre oscuro */
    --gothic-red-light: #b22222;      /* Rojo sangre vibrante */
    --gothic-border: #2c2c2c;         /* Borde oscuro sutil */
    --gothic-shadow: rgba(0, 0, 0, 0.6); /* Sombra oscura */
  }

  /* --- Globals y Elementos Base --- */
  ytd-app,
  body,
  html,
  #page-manager,
  ytd-watch-flexy,
  #content {
    background-color: var(--gothic-bg-darkest) !important;
    color: var(--gothic-text-light) !important;
    font-family: 'Times New Roman', serif !important;
  }

  /* Barras de desplazamiento */
  ::-webkit-scrollbar {
    width: 10px !important;
  }
  ::-webkit-scrollbar-track {
    background: var(--gothic-bg-dark) !important;
  }
  ::-webkit-scrollbar-thumb {
    background-color: var(--gothic-red-accent) !important;
    border-radius: 5px !important;
    border: 2px solid var(--gothic-bg-darkest) !important;
  }
  ::-webkit-scrollbar-corner {
    background: var(--gothic-bg-darkest) !important;
  }

  /* --- Cabecera y Navegación --- */
  #masthead-container,
  ytd-masthead {
    background-color: var(--gothic-bg-dark) !important;
    border-bottom: 1px solid var(--gothic-border) !important;
    box-shadow: 0 2px 5px var(--gothic-shadow) !important;
  }

  /* Logo de YouTube */
  #logo-icon {
    filter: invert(1) sepia(1) saturate(5) hue-rotate(300deg) brightness(0.8) contrast(1.2) !important;
  }

  #country-code {
    color: var(--gothic-text-medium) !important;
  }

  /* Iconos de cabecera (notificaciones, avatar, etc.) */
  yt-icon-button {
    --yt-icon-button-fill: var(--gothic-text-light) !important;
    --yt-icon-button-hover-fill: var(--gothic-red-light) !important;
  }
  yt-icon-button:hover {
    background-color: var(--gothic-bg-medium) !important;
    border-radius: 50% !important;
  }

  /* Barra de búsqueda */
  ytd-searchbox #container {
    background-color: var(--gothic-bg-medium) !important;
    border: 1px solid var(--gothic-border) !important;
    border-radius: 5px !important;
  }
  ytd-searchbox #search-input {
    color: var(--gothic-text-light) !important;
  }
  ytd-searchbox #search-icon-legacy {
    background-color: var(--gothic-red-accent) !important;
    color: var(--gothic-text-light) !important;
    border-radius: 0 5px 5px 0 !important;
    border: none !important;
  }
  ytd-searchbox #search-icon-legacy:hover {
    background-color: var(--gothic-red-light) !important;
  }

  /* --- Barra Lateral de Navegación --- */
  ytd-mini-guide-renderer,
  ytd-guide-renderer {
    background-color: var(--gothic-bg-dark) !important;
    border-right: 1px solid var(--gothic-border) !important;
  }

  ytd-guide-entry-renderer {
    color: var(--gothic-text-light) !important;
    font-family: 'Times New Roman', serif !important;
  }
  ytd-guide-entry-renderer:hover,
  ytd-guide-entry-renderer.selected {
    background-color: var(--gothic-bg-medium) !important;
  }
  ytd-guide-entry-renderer.selected {
    border-left: 3px solid var(--gothic-red-accent) !important;
  }
  ytd-guide-entry-renderer yt-icon {
    --yt-icon-color: var(--gothic-text-medium) !important;
  }
  ytd-guide-entry-renderer.selected yt-icon {
    --yt-icon-color: var(--gothic-red-light) !important;
  }

  /* Títulos de sección en sidebar */
  ytd-guide-section-renderer #title {
    color: var(--gothic-text-medium) !important;
    font-family: 'Playfair Display', serif !important;
    text-transform: uppercase !important;
    font-size: 0.9em !important;
    margin-top: 15px !important;
  }

  /* --- Contenido Principal y Videos --- */
  #contents,
  ytd-two-column-browse-results-renderer #primary,
  ytd-rich-grid-renderer,
  ytd-item-section-renderer {
    background-color: var(--gothic-bg-darkest) !important;
  }

  /* Miniaturas de video y contenedores */
  ytd-grid-video-renderer,
  ytd-compact-video-renderer,
  ytd-playlist-video-renderer,
  ytd-rich-grid-media,
  ytd-video-renderer,
  ytd-shelf-renderer {
    background-color: var(--gothic-bg-dark) !important;
    border: 1px solid var(--gothic-border) !important;
    border-radius: 8px !important;
    box-shadow: 0 3px 10px var(--gothic-shadow) !important;
    transition: transform 0.3s ease, box-shadow 0.3s ease !important;
  }

  ytd-grid-video-renderer:hover,
  ytd-rich-grid-media:hover,
  ytd-video-renderer:hover {
    transform: translateY(-3px) !important;
    box-shadow: 0 6px 15px var(--gothic-shadow) !important;
  }

  /* Títulos de video */
  #video-title.ytd-grid-video-renderer,
  #video-title.ytd-compact-video-renderer,
  #video-title.ytd-video-renderer,
  #video-title.ytd-rich-grid-media {
    color: var(--gothic-text-light) !important;
    font-family: 'Playfair Display', serif !important;
    font-weight: 600 !important;
    line-height: 1.3 !important;
  }

  /* Nombre del canal y metadatos */
  #channel-name yt-formatted-string,
  #metadata-line span,
  #byline-container yt-formatted-string,
  .ytd-video-meta-block {
    color: var(--gothic-text-medium) !important;
    font-family: 'Montserrat', sans-serif !important;
  }

  /* --- Controles del Reproductor --- */
  .ytp-progress-bar-container {
    background-color: rgba(0, 0, 0, 0.7) !important;
  }
  .ytp-play-progress,
  .ytp-load-progress {
    background-color: var(--gothic-red-accent) !important;
  }
  .ytp-scrubber-button {
    background-color: var(--gothic-red-light) !important;
    border: 1px solid var(--gothic-text-light) !important;
  }
  .ytp-volume-slider-handle {
    background-color: var(--gothic-red-accent) !important;
  }
  .ytp-settings-button,
  .ytp-chrome-controls .ytp-button {
    color: var(--gothic-text-light) !important;
  }

  /* --- Página de Reproducción de Video --- */
  ytd-watch-flexy #primary,
  ytd-watch-flexy #secondary {
    background-color: var(--gothic-bg-darkest) !important;
  }

  h1.ytd-video-primary-info-renderer {
    color: var(--gothic-text-light) !important;
    font-family: 'Playfair Display', serif !important;
    font-size: 2.2em !important;
    line-height: 1.2 !important;
  }

  #description.ytd-video-secondary-info-renderer {
    color: var(--gothic-text-medium) !important;
    font-family: 'Montserrat', sans-serif !important;
  }

  /* Botones bajo el video */
  ytd-menu-renderer .yt-icon-button,
  .yt-spec-button-shape-next {
    background-color: var(--gothic-bg-dark) !important;
    color: var(--gothic-text-light) !important;
    border: 1px solid var(--gothic-border) !important;
    border-radius: 5px !important;
    font-family: 'Montserrat', sans-serif !important;
  }
  ytd-menu-renderer .yt-icon-button:hover,
  .yt-spec-button-shape-next:hover {
    background-color: var(--gothic-bg-medium) !important;
  }

  yt-icon {
    --yt-icon-color: var(--gothic-text-medium) !important;
  }

  /* --- Sección de Comentarios --- */
  #comments,
  ytd-comments,
  ytd-item-section-renderer[is-comments] {
    background-color: var(--gothic-bg-darkest) !important;
  }

  ytd-comments-header-renderer #title {
    color: var(--gothic-text-light) !important;
    font-family: 'Playfair Display', serif !important;
  }

  ytd-comment-renderer {
    background-color: var(--gothic-bg-dark) !important;
    border: 1px solid var(--gothic-border) !important;
    border-radius: 5px !important;
    margin-bottom: 10px !important;
    padding: 15px !important;
  }

  #author-text.ytd-comment-renderer {
    color: var(--gothic-red-light) !important;
    font-weight: bold !important;
  }

  #comment-text.ytd-comment-renderer {
    color: var(--gothic-text-light) !important;
  }

  /* Input de comentarios */
  ytd-commentbox #placeholder-area,
  ytd-commentbox #contenteditable-root {
    background-color: var(--gothic-bg-medium) !important;
    border: 1px solid var(--gothic-border) !important;
    color: var(--gothic-text-light) !important;
    border-radius: 5px !important;
  }

  ytd-commentbox #submit-button {
    background-color: var(--gothic-bg-dark) !important;
    color: var(--gothic-text-light) !important;
    border: 1px solid var(--gothic-border) !important;
  }

  ytd-commentbox #submit-button:hover {
    background-color: var(--gothic-bg-medium) !important;
  }

  /* --- Listas de Reproducción --- */
  ytd-playlist-panel-renderer {
    background-color: var(--gothic-bg-dark) !important;
    border-left: 1px solid var(--gothic-border) !important;
  }

  ytd-playlist-panel-renderer #title {
    color: var(--gothic-text-light) !important;
    font-family: 'Playfair Display', serif !important;
  }

  ytd-playlist-panel-video-renderer.selected {
    background-color: var(--gothic-bg-medium) !important;
    border-left: 3px solid var(--gothic-red-accent) !important;
  }

  ytd-playlist-panel-video-renderer:hover {
    background-color: var(--gothic-bg-medium) !important;
  }
}
